/**
 * Email Configuration — Nodemailer setup with transactional email support
 * Generated by BackendForge
 */

const nodemailer = require('nodemailer');
const { env } = require('./env');

const transporter = nodemailer.createTransport({
  host: env.SMTP_HOST,
  port: parseInt(env.SMTP_PORT),
  secure: parseInt(env.SMTP_PORT) === 465,
  auth: {
    user: env.SMTP_USER,
    pass: env.SMTP_PASS,
  },
});

/**
 * Send an email.
 * @param {object} options - { to, subject, html, text }
 */
const sendEmail = async ({ to, subject, html, text }) => {
  try {
    const info = await transporter.sendMail({
      from: env.EMAIL_FROM,
      to,
      subject,
      html,
      text,
    });
    return { success: true, messageId: info.messageId };
  } catch (error) {
    console.error(`Email send failed: ${error.message}`);
    return { success: false, error: error.message };
  }
};

/**
 * Verify email transport connection.
 */
const verifyEmailTransport = async () => {
  try {
    await transporter.verify();
    return true;
  } catch {
    console.warn('Email transport verification failed — emails may not be sent');
    return false;
  }
};

module.exports = { sendEmail, verifyEmailTransport, transporter };
